   188→    [MethodImpl(MethodImplOptions.NoInlining)]
   189→    private static (uint baseLength, uint expLength, uint modulusLength) GetInputLengthsMayOverflow(ReadOnlySpan<byte> inputData)
   190→    {
   191→        // Only valid if baseLength and modulusLength are zero; when expLength doesn't matter
   192→        if (Vector256<byte>.IsSupported)
   193→        {
   194→            ref var firstByte = ref MemoryMarshal.GetReference(inputData);
   195→            if (Vector256.BitwiseOr(
   196→                    Unsafe.ReadUnaligned<Vector256<byte>>(ref firstByte),
   197→                    Unsafe.ReadUnaligned<Vector256<byte>>(ref Unsafe.Add(ref firstByte, StartModLength)))
   198→                != Vector256<byte>.Zero)
   199→            {
   200→                // Overflow
   201→                return (uint.MaxValue, uint.MaxValue, uint.MaxValue);
   202→            }
   203→        }
   204→        else if (Vector128<byte>.IsSupported)
   205→        {
   206→            ref var firstByte = ref MemoryMarshal.GetReference(inputData);
   207→            if (Vector128.BitwiseOr(
   208→                    Vector128.BitwiseOr(
   209→                        Unsafe.ReadUnaligned<Vector128<byte>>(ref firstByte),
   210→                        Unsafe.ReadUnaligned<Vector128<byte>>(ref Unsafe.Add(ref firstByte, 16))),
   211→                    Vector128.BitwiseOr(
   212→                        Unsafe.ReadUnaligned<Vector128<byte>>(ref Unsafe.Add(ref firstByte, StartModLength)),
   213→                        Unsafe.ReadUnaligned<Vector128<byte>>(ref Unsafe.Add(ref firstByte, StartModLength + 16)))
   214→                ) != Vector128<byte>.Zero)
   215→            {
   216→                // Overflow
   217→                return (uint.MaxValue, uint.MaxValue, uint.MaxValue);
   218→            }
   219→        }
   220→        else if (inputData.Slice(StartBaseLength, LengthSize).IndexOfAnyExcept((byte)0) >= 0 ||
   221→                inputData.Slice(StartModLength, LengthSize).IndexOfAnyExcept((byte)0) >= 0)
   222→        {
   223→            // Overflow
   224→            return (uint.MaxValue, uint.MaxValue, uint.MaxValue);
   225→        }
   226→
   227→        return (0, uint.MaxValue, 0);
   228→    }
   229→
   230→    public unsafe (byte[], bool) Run(ReadOnlyMemory<byte> inputData, IReleaseSpec releaseSpec)
   231→    {
   232→        Metrics.ModExpPrecompile++;
   233→
   234→        ReadOnlySpan<byte> inputSpan = inputData.Span;
   235→        (uint baseLength, uint expLength, uint modulusLength) = inputSpan.Length >= LengthsLengths
   236→                ? GetInputLengths(inputSpan)
   237→                : GetInputLengthsShort(inputSpan);
   238→
   239→        if (ExceedsMaxInputSize(releaseSpec, baseLength, expLength, modulusLength))
   240→            return IPrecompile.Failure;
   241→
   242→        // if both are 0, then expLength can be huge, which leads to a potential buffer too big exception
   243→        if (baseLength == 0 && modulusLength == 0)
   244→            return (Bytes.Empty, true);
   245→
   246→        using var modulusInt = mpz_t.Create();
   247→
   248→        ReadOnlySpan<byte> modulusDataSpan = inputSpan.SliceWithZeroPaddingEmptyOnError(96 + (int)baseLength + (int)expLength, (int)modulusLength);
   249→        if (modulusDataSpan.Length > 0)
   250→        {
   251→            fixed (byte* modulusData = &MemoryMarshal.GetReference(modulusDataSpan))
   252→                Gmp.mpz_import(modulusInt, modulusLength, 1, 1, 1, nuint.Zero, (nint)modulusData);
   253→        }
   254→
   255→        if (Gmp.mpz_sgn(modulusInt) == 0)
   256→            return (new byte[modulusLength], true);
   257→
   258→        using var baseInt = mpz_t.Create();
   259→        using var expInt = mpz_t.Create();
   260→        using var powmResult = mpz_t.Create();
   261→
   262→        ReadOnlySpan<byte> baseDataSpan = inputSpan.SliceWithZeroPaddingEmptyOnError(96, (int)baseLength);
   263→        if (baseDataSpan.Length > 0)
   264→        {
   265→            fixed (byte* baseData = &MemoryMarshal.GetReference(baseDataSpan))
   266→                Gmp.mpz_import(baseInt, baseLength, 1, 1, 1, nuint.Zero, (nint)baseData);
   267→        }
   268→
   269→        ReadOnlySpan<byte> expDataSpan = inputSpan.SliceWithZeroPaddingEmptyOnError(96 + (int)baseLength, (int)expLength);
   270→        if (expDataSpan.Length > 0)
   271→        {
   272→            fixed (byte* expData = &MemoryMarshal.GetReference(expDataSpan))
   273→                Gmp.mpz_import(expInt, expLength, 1, 1, 1, nuint.Zero, (nint)expData);
   274→        }
   275→
   276→        Gmp.mpz_powm(powmResult, baseInt, expInt, modulusInt);
   277→
   278→        nint powmResultLen = (nint)(Gmp.mpz_sizeinbase(powmResult, 2) + 7) / 8;
   279→        nint offset = (int)modulusLength - powmResultLen;
   280→
   281→        byte[] result = new byte[modulusLength];
   282→        fixed (byte* ptr = &MemoryMarshal.GetArrayDataReference(result))
   283→            Gmp.mpz_export((nint)(ptr + offset), out _, 1, 1, 1, nuint.Zero, powmResult);
   284→
   285→        return (result, true);
   286→    }
   287→
   288→    /// <summary>
   289→    /// def calculate_multiplication_complexity(base_length, modulus_length):
   290→    /// max_length = max(base_length, modulus_length)
   291→    /// words = math.ceil(max_length / 8)
   292→    /// return words**2
   293→    /// </summary>
   294→    /// <returns></returns>
   295→    private static ulong MultComplexity(uint baseLength, uint modulusLength, bool isEip7883Enabled)
   296→    {
   297→        // Pick the larger of the two  
   298→        uint max = baseLength > modulusLength ? baseLength : modulusLength;
   299→
   300→        // Compute ceil(max/8) via a single add + shift
   301→        // (max + 7) >> 3  ==  (max + 7) / 8, rounding up
   302→        ulong words = ((ulong)max + 7u) >> 3;
   303→
   304→        // Square it once
   305→        ulong sq = words * words;
   306→
   307→        // If EIP-7883 => small-case = 16, else 2*sq when max>32
   308→        if (isEip7883Enabled)
   309→        {
   310→            return max > LengthSize
   311→                ? (sq << 1)    // 2 * words * words
   312→                : 16UL;        // constant floor
   313→        }
   314→
   315→        // Otherwise plain square
   316→        return sq;
   317→    }
   318→
   319→    static readonly ulong IterationCountMultiplierEip2565 = 8;
   320→
   321→    static readonly ulong IterationCountMultiplierEip7883 = 16;
   322→
   323→    /// <summary>
   324→    /// def calculate_iteration_count(exponent_length, exponent):
   325→    /// iteration_count = 0
   326→    /// if exponent_length &lt;= 32 and exponent == 0: iteration_count = 0
   327→    /// elif exponent_length &lt;= 32: iteration_count = exponent.bit_length() - 1
   328→    /// elif exponent_length > 32: iteration_count = (8 * (exponent_length - 32)) + ((exponent & (2**256 - 1)).bit_length() - 1)
   329→    /// return max(iteration_count, 1)
   330→    /// </summary>
   331→    /// <param name="exponentLength"></param>
   332→    /// <param name="exponent"></param>
   333→    /// <param name="isEip7883Enabled"></param>
   334→    /// <returns></returns>
   335→    private static UInt256 CalculateIterationCount(uint exponentLength, UInt256 exponent, bool isEip7883Enabled)
   336→    {
   337→        ulong iterationCount;
   338→        uint overflow = 0;
   339→        if (exponentLength <= LengthSize)
   340→        {
   341→            iterationCount = (uint)Math.Max(1, exponent.BitLen - 1);
   342→        }
   343→        else
   344→        {
   345→            uint bitLength = (uint)exponent.BitLen;
   346→            if (bitLength > 0)
   347→            {
   348→                bitLength--;
   349→            }
   350→
   351→            ulong multiplicationResult = (exponentLength - LengthSize) * (isEip7883Enabled ? IterationCountMultiplierEip7883 : IterationCountMultiplierEip2565);
   352→            iterationCount = multiplicationResult + bitLength;
   353→            if (iterationCount < multiplicationResult)
   354→            {
   355→                // Overflowed
   356→                overflow = 1;
   357→            }
   358→            else if (iterationCount < 1)
   359→            {
   360→                // Min 1 iteration
   361→                iterationCount = 1;
   362→            }
   363→        }
   364→
   365→        return new UInt256(iterationCount, overflow);
   366→    }
   367→}
