      "code_excerpt": "// PRIMARY: src/Nethermind/Nethermind.Core/ExecutionRequest/ExecutionRequestExtensions.cs:CalculateHashFromFlatEncodedRequests (lines 33-50)\npublic static Hash256 CalculateHashFromFlatEncodedRequests(byte[][]? flatEncodedRequests)\n{\n    if (flatEncodedRequests is null) throw new ArgumentException(...);\n    using ArrayPoolList<byte> concatenatedHashes = new(Hash256.Size * MaxRequestsCount);\n    foreach (byte[] requests in flatEncodedRequests)\n    {\n        if (requests.Length <= 1) continue;  // Skip empty request arrays\n        concatenatedHashes.AddRange(SHA256.HashData(requests));  // Inner: hash each request type\n    }\n    // Outer: SHA256 of all concatenated inner hashes\n    return new Hash256(SHA256.HashData(concatenatedHashes.UnsafeGetInternalArray().AsSpan(0, concatenatedHashes.Count)));\n}"
